import pty,os,subprocess,time,select
def make():
 m,s=pty.openpty(); return m,s
def drain(fd):
 out=b''; os.set_blocking(fd,False)
 try:
  while True:
   d=os.read(fd,8192)
   if not d:break
   out+=d
 except:pass
 return out
def run(args,stdin='tty',stdout='pipe',wait=.5):
