      "  --large_window=NUM          use incompatible large-window brotli\n"
      "                              bitstream with window size (0, 10-30)\n"
      "                              WARNING: this format is not compatible\n"
      "                              with brotli RFC 7932 and may not be\n"
      "                              decodable with regular brotli decoders\n"
      "  -C B64, --comment=B64       set comment; argument is base64-decoded first;\n"
      "                              (maximal decoded length: 80)\n"
      "                              when decoding: check stream comment;\n"
      "                              when encoding: embed comment (fingerprint)\n"
      "  -D FILE, --dictionary=FILE  use FILE as raw (LZ77) dictionary\n"
      "  -K, --concatenated          allows concatenated brotli streams as input\n"
      "  -S SUF, --suffix=SUF        output file suffix (default:'.br')\n"
      "  -V, --version               display version and exit\n"
      "  -Z, --best                  use best compression level (11) (default)\n"
      "Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.\n"
      "With no FILE, or when FILE is -, read standard input.\n"
      "All arguments after '--' are treated as files.\n",
      g_program_name);
}

static _Noreturn void ParseFail(const char* message) {
  if (message && *message) fprintf(stderr, "%s", message);
  PrintHelp(stdout);
  exit(1);
}

static _Noreturn void ParseFailFmt1(const char* format, const char* arg) {
  fprintf(stderr, format, arg);
  PrintHelp(stdout);
  exit(1);
}

static _Noreturn void ShowHelpAndExit(void) {
  PrintHelp(stderr);
  exit(0);
}

static _Noreturn void ShowVersionAndExit(void) {
  fprintf(stdout, "brotli 1.2.0\n");
  exit(0);
}

static void AddFilename(Params* p, char* name) {
  if (!name || !*name) return;
  if (p->filename_count == p->filename_capacity) {
    size_t ncap = p->filename_capacity ? p->filename_capacity * 2 : 16;
    char** n = (char**)realloc(p->filenames, ncap * sizeof(char*));
    if (!n) exit(1);
    p->filenames = n;
    p->filename_capacity = ncap;
  }
  p->filenames[p->filename_count++] = name;
}

static int Base64Value(unsigned char c) {
  if (c >= 'A' && c <= 'Z') return c - 'A';
  if (c >= 'a' && c <= 'z') return c - 'a' + 26;
  if (c >= '0' && c <= '9') return c - '0' + 52;
  if (c == '+' || c == '-') return 62;
  if (c == '/' || c == '_') return 63;
  return -1;
}

static bool DecodeBase64Comment(const char* text, uint8_t** out, size_t* out_len) {
  /* The reference decoder skips SP, TAB, CR and LF, accepts both the
     standard and URL-safe alphabets, tolerates one or two trailing '='
     characters (also after a complete group), and decodes an incomplete
     final group of two or three sextets.  A lone trailing sextet is
     discarded. */
  size_t sextets = 0;
  size_t pads = 0;
  bool seen_pad = false;
  const unsigned char* s = (const unsigned char*)text;
  for (size_t i = 0; s[i]; i++) {
    unsigned char c = s[i];
    if (c == ' ' || c == '\t' || c == '\r' || c == '\n') continue;
    if (c == '=') {
      if (sextets == 0 || (sextets % 4) == 1) return false;
      seen_pad = true;
      pads++;
      if (pads > 2) return false;
      continue;
    }
    if (seen_pad) return false;
    if (Base64Value(c) < 0) return false;
    sextets++;
  }
  size_t decoded_len = (sextets * 6) / 8;
  if (decoded_len > 80) return false;
  uint8_t* buf = (uint8_t*)malloc(decoded_len ? decoded_len : 1);
  if (!buf) return false;
  uint32_t acc = 0;
  int acc_bits = 0;
  size_t pos = 0;
  for (size_t i = 0; s[i]; i++) {
    unsigned char c = s[i];
    if (c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '=') continue;
    int v = Base64Value(c);
    acc = (acc << 6) | (uint32_t)v;
    acc_bits += 6;
    if (acc_bits >= 8) {
      acc_bits -= 8;
      if (pos < decoded_len) buf[pos++] = (uint8_t)((acc >> acc_bits) & 0xffu);
    }
  }
  *out = buf;
  *out_len = decoded_len;
  return true;
}

static bool ParseQualityValue(const char* s, int* value) {
  size_t len = strlen(s);
  if (len == 1 && s[0] >= '0' && s[0] <= '9') {
    *value = s[0] - '0';
    return true;
  }
  if (len == 2 && s[0] == '1' && (s[1] == '0' || s[1] == '1')) {
    *value = 10 + (s[1] - '0');
    return true;
  }
  return false;
}

/* Returns 1 ok, 0 generic parse error, -1 "smaller than minimum". */
static int ParseLgwinValue(const char* s, int max_value, int* value, int* small_value) {
  size_t len = strlen(s);
  if (len == 1 && s[0] >= '0' && s[0] <= '9') {
    int v = s[0] - '0';
    if (v == 0) {
      *value = 0;
      return 1;
    }
    *small_value = v;
    return -1;
  }
  if (len == 2 && s[0] >= '0' && s[0] <= '9' && s[1] >= '0' && s[1] <= '9') {
    int v = (s[0] - '0') * 10 + (s[1] - '0');
    if (v >= 10 && v <= max_value) {
      *value = v;
      return 1;
    }
  }
  return 0;
}

static void SetQuality(Params* p, int quality) {
  if (p->quality_set) ParseFail("quality already set\n");
  p->quality_set = true;
  p->quality = quality;
}

static void SetCommand(Params* p, Command command, const char* spelling) {
  if (p->command_set) {
    fprintf(stderr, "command already set when parsing %s\n", spelling);
    PrintHelp(stdout);
    exit(1);
  }
  p->command_set = true;
  p->command = command;
}

static void SetStdout(Params* p) {
  if (p->to_stdout) ParseFail("write to standard output already set\n");
  p->to_stdout = true;
}

static void HandleQualityParameter(Params* p, const char* value) {
  if (p->quality_set) ParseFail("quality already set\n");
  int q;
  if (!ParseQualityValue(value, &q)) {
    ParseFailFmt1("error parsing quality value [%s]\n", value);
  }
  p->quality_set = true;
  p->quality = q;
}

static void HandleLgwinParameter(Params* p, const char* value, bool large) {
  if (p->lgwin_set) ParseFail("lgwin parameter already set\n");
  int v = 0;
  int small = 0;
  int r = ParseLgwinValue(value, large ? 30 : 24, &v, &small);
  if (r == -1) {
    fprintf(stderr, "lgwin parameter (%d) smaller than the minimum (10)\n", small);
    PrintHelp(stdout);
    exit(1);
  }
  if (r == 0) ParseFailFmt1("error parsing lgwin value [%s]\n", value);
  p->lgwin_set = true;
  p->lgwin = v;
  p->large_window = large && v > 24;
}

static void HandleOutputParameter(Params* p, const char* value, bool long_form) {
  if (p->to_stdout) {
    ParseFail(long_form ? "write to standard output already set (--output)\n"
                        : "write to standard output already set (-o)\n");
  }
  p->output_path = value;
}

static void HandleSuffixParameter(Params* p, const char* value) {
  if (p->suffix_set) ParseFail("suffix already set\n");
  p->suffix_set = true;
  p->suffix = value;
}

static void HandleCommentParameter(Params* p, const char* value) {
  if (p->comment_set) ParseFail("comment already set\n");
  uint8_t* decoded = NULL;
  size_t len = 0;
  if (!DecodeBase64Comment(value, &decoded, &len)) {
    ParseFail("invalid base64-encoded comment\n");
  }
  p->comment_set = true;
  p->comment = decoded;
  p->comment_len = len;
}

static void HandleDictionaryParameter(Params* p, const char* value) {
  if (p->dictionary_path) ParseFail("dictionary path already set\n");
  p->dictionary_path = value;
}

static void ParseLongParameter(Params* p, const char* name) {
  const char* eq = strchr(name, '=');
  if (!eq || eq[1] == '\0') {
    ParseFailFmt1("must pass the parameter as --%s=value\n", name);
  }
  size_t name_len = (size_t)(eq - name);
  const char* value = eq + 1;
  /* Prefix matching on the part before '='.  The order matters for the
     degenerate cases: an empty name is a comment, and "l" is lgwin rather
     than large_window. */
  if (strncmp(name, "comment", name_len) == 0) {
    HandleCommentParameter(p, value);
  } else if (strncmp(name, "dictionary", name_len) == 0) {
    HandleDictionaryParameter(p, value);
  } else if (strncmp(name, "lgwin", name_len) == 0) {
    HandleLgwinParameter(p, value, false);
  } else if (strncmp(name, "large_window", name_len) == 0) {
    HandleLgwinParameter(p, value, true);
  } else if (strncmp(name, "output", name_len) == 0) {
    HandleOutputParameter(p, value, true);
  } else if (strncmp(name, "quality", name_len) == 0) {
    HandleQualityParameter(p, value);
  } else if (strncmp(name, "suffix", name_len) == 0) {
    HandleSuffixParameter(p, value);
  } else {
    ParseFailFmt1("invalid parameter: [%s]\n", name);
  }
}

static void ParseLongOption(Params* p, const char* arg) {
  const char* name = arg + 2;
  if (strcmp(name, "stdout") == 0) {
    SetStdout(p);
  } else if (strcmp(name, "decompress") == 0) {
    SetCommand(p, CMD_DECOMPRESS, "--decompress");
  } else if (strcmp(name, "force") == 0) {
    if (p->force) ParseFail("force output overwrite already set\n");
    p->force = true;
  } else if (strcmp(name, "help") == 0) {
    ShowHelpAndExit();
  } else if (strcmp(name, "rm") == 0) {
    if (p->keep_rm_set) ParseFail("argument --rm / -j or --keep / -k already set\n");
    p->keep_rm_set = true;
    p->rm = true;
  } else if (strcmp(name, "squash") == 0) {
    if (p->squash) ParseFail("argument --squash / -s already set\n");
    p->squash = true;
  } else if (strcmp(name, "keep") == 0) {
    if (p->keep_rm_set) ParseFail("argument --rm / -j or --keep / -k already set\n");
    p->keep_rm_set = true;
    p->rm = false;
  } else if (strcmp(name, "no-copy-stat") == 0) {
    if (p->no_copy_stat) ParseFail("argument --no-copy-stat / -n already set\n");
    p->no_copy_stat = true;
  } else if (strcmp(name, "test") == 0) {
    SetCommand(p, CMD_TEST, "--test");
  } else if (strcmp(name, "verbose") == 0) {
    if (p->verbose) ParseFail("argument --verbose / -v already set\n");
    p->verbose = true;
  } else if (strcmp(name, "concatenated") == 0) {
    if (p->concatenated) ParseFail("argument -K / --concatenated already set\n");
    p->concatenated = true;
  } else if (strcmp(name, "version") == 0) {
    ShowVersionAndExit();
  } else if (strcmp(name, "best") == 0) {
    SetQuality(p, 11);
  } else {
    ParseLongParameter(p, name);
  }
}

static void ParseShortOptions(Params* p, int argc, char** argv, int* index) {
  const char* arg = argv[*index];
  size_t len = strlen(arg);
  for (size_t j = 1; j < len; j++) {
    char c = arg[j];
    if (c >= '0' && c <= '9') {
      SetQuality(p, c - '0');
      continue;
    }
    switch (c) {
      case 'c': SetStdout(p); break;
      case 'd': SetCommand(p, CMD_DECOMPRESS, "-d"); break;
      case 'f':
        if (p->force) ParseFail("force output overwrite already set\n");
        p->force = true;
        break;
      case 'h': ShowHelpAndExit(); break;
      case 'j':
        if (p->keep_rm_set) ParseFail("argument --rm / -j or --keep / -k already set\n");
        p->keep_rm_set = true;
        p->rm = true;
        break;
      case 's':
        if (p->squash) ParseFail("argument --squash / -s already set\n");
        p->squash = true;
        break;
      case 'k':
        if (p->keep_rm_set) ParseFail("argument --rm / -j or --keep / -k already set\n");
        p->keep_rm_set = true;
        p->rm = false;
        break;
      case 'n':
        if (p->no_copy_stat) ParseFail("argument --no-copy-stat / -n already set\n");
        p->no_copy_stat = true;
        break;
      case 't': SetCommand(p, CMD_TEST, "-t"); break;
      case 'v':
        if (p->verbose) ParseFail("argument --verbose / -v already set\n");
        p->verbose = true;
        break;
      case 'K':
        if (p->concatenated) ParseFail("argument -K / --concatenated already set\n");
        p->concatenated = true;
        break;
      case 'V': ShowVersionAndExit(); break;
      case 'Z': SetQuality(p, 11); break;
      case 'q':
      case 'w':
      case 'o':
      case 'S':
      case 'C':
      case 'D': {
        if (j + 1 != len || *index + 1 >= argc || argv[*index + 1][0] == '\0') {
          fprintf(stderr, "expected parameter for argument -%c\n", c);
          PrintHelp(stdout);
          exit(1);
        }
        const char* value = argv[++(*index)];
        if (c == 'q') HandleQualityParameter(p, value);
        else if (c == 'w') HandleLgwinParameter(p, value, false);
        else if (c == 'o') HandleOutputParameter(p, value, false);
        else if (c == 'S') HandleSuffixParameter(p, value);
        else if (c == 'C') HandleCommentParameter(p, value);
        else HandleDictionaryParameter(p, value);
        break;
      }
      default:
        fprintf(stderr, "invalid argument -%c\n", c);
        PrintHelp(stdout);
        exit(1);
    }
  }
}

static void ParseArgs(Params* p, int argc, char** argv) {
  bool files_only = false;
  for (int i = 1; i < argc; i++) {
    char* arg = argv[i];
    if (arg[0] == '\0') continue;
    if (files_only) {
      AddFilename(p, arg);
      continue;
    }
    if (strcmp(arg, "--") == 0) {
      files_only = true;
      continue;
    }
    if (arg[0] == '-' && arg[1] == '-' && arg[2] != '\0') {
      ParseLongOption(p, arg);
    } else if (arg[0] == '-' && arg[1] != '\0') {
      ParseShortOptions(p, argc, argv, &i);
    } else {
      AddFilename(p, arg);
    }
  }

  if (strchr(p->suffix, '/') || strchr(p->suffix, '\\')) {
    PrintHelp(stdout);
    exit(1);
  }
  if (p->concatenated && (p->command != CMD_DECOMPRESS || p->comment_len > 0)) {
    PrintHelp(stdout);
    exit(1);
  }
  if (p->squash && p->to_stdout) {
    PrintHelp(stdout);
    exit(1);
  }
  if (p->command == CMD_TEST && (p->to_stdout || p->output_path)) {
    PrintHelp(stdout);
    exit(1);
  }
  if (p->to_stdout && p->filename_count > 1) {
    PrintHelp(stdout);
    exit(1);
  }
}

static const char* BaseName(const char* path) {
  const char* last = path;
  for (const char* s = path; *s; s++) {
    if (*s == '/' || *s == '\\') last = s + 1;
  }
  return last;
}

static double NowSeconds(void) {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
}

static void FormatSize(uint64_t size, char* buf, size_t buf_size) {
  static const char* units[] = {"B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"};
  if (size < 1024) {
    snprintf(buf, buf_size, "%" PRIu64 " B", size);
    return;
  }
  double value = (double)size;
  size_t unit = 0;
  while (value >= 1024.0 && unit + 1 < sizeof(units) / sizeof(units[0])) {
    value /= 1024.0;
    unit++;
  }
  snprintf(buf, buf_size, "%.3f %s", value, units[unit]);
}

static bool ReadDictionary(const char* path) {
  FILE* f = fopen(path, "rb");
  if (!f) {
    fprintf(stderr, "failed to open dictionary file [%s]: %s\n", path, strerror(errno));
    return false;
  }
  struct stat st;
  int64_t size = 0;
  if (fstat(fileno(f), &st) == 0) size = (int64_t)st.st_size;
  if (size == 0) {
    if (fseeko(f, 0, SEEK_END) != 0) {
      fprintf(stderr, "could not get size of dictionary file [%s]", path);
      fclose(f);
      return false;
    }
    off_t pos = ftello(f);
    if (pos < 0) {
      fprintf(stderr, "could not get size of dictionary file [%s]", path);
      fclose(f);
      return false;
    }
    size = (int64_t)pos;
    fseeko(f, 0, SEEK_SET);
  }
  if (size < 0) {
    fprintf(stderr, "could not get size of dictionary file [%s]", path);
    fclose(f);
    return false;
  }
  if ((uint64_t)size > DICTIONARY_MAX_SIZE) {
    fprintf(stderr, "dictionary [%s] is larger than maximum allowed: %u\n", path, DICTIONARY_MAX_SIZE);
    fclose(f);
    return false;
  }
  g_dictionary = (uint8_t*)malloc(size ? (size_t)size : 1);
  if (!g_dictionary) {
    fclose(f);
    return false;
  }
  g_dictionary_len = size ? fread(g_dictionary, 1, (size_t)size, f) : 0;
  fclose(f);
  return true;
}

static FILE* OpenOutputFile(const char* path, bool force) {
  int flags = O_WRONLY | O_CREAT | (force ? O_TRUNC : O_EXCL);
  int fd = open(path, flags, 0600);
  if (fd < 0) return NULL;
  FILE* f = fdopen(fd, "wb");
  if (!f) {
    int saved = errno;
    close(fd);
    errno = saved;
    return NULL;
  }
  return f;
}

static void CopyStat(const char* from, const char* to) {
  struct stat st;
  if (stat(from, &st) != 0) return;
  if (chmod(to, st.st_mode & 0777) != 0) {
    fprintf(stderr, "setting access bits failed for [%s]: %s\n", to, strerror(errno));
  }
  if (chown(to, (uid_t)-1, st.st_gid) != 0) {
    fprintf(stderr, "setting group failed for [%s]: %s\n", to, strerror(errno));
  }
  if (chown(to, st.st_uid, (gid_t)-1) != 0) {
    fprintf(stderr, "setting user failed for [%s]: %s\n", to, strerror(errno));
  }
  struct timespec times[2];
  times[0].tv_sec = 0;
  times[0].tv_nsec = UTIME_NOW;
  times[1] = st.st_mtim;
  (void)utimensat(AT_FDCWD, to, times, 0);
}

static int EffectiveLgwin(const Params* p, FILE* input, bool input_is_stdin) {
  if (p->lgwin != 0) return p->lgwin;
  if (input_is_stdin) return 24;
  off_t current = ftello(input);
  if (current < 0) return 24;
  if (fseeko(input, 0, SEEK_END) != 0) return 24;
  off_t size = ftello(input);
  (void)fseeko(input, current, SEEK_SET);
  if (size < 0) return 24;
  for (int w = 10; w <= 24; w++) {
    int64_t capacity = ((int64_t)1 << w) - 16;
    if ((int64_t)size <= capacity) return w;
  }
  return 24;
}

/* Bit utilities (LSB-first) used for window-bit parsing and metadata. */
static int GetBit(const uint8_t* data, size_t bit_pos) {
  return (data[bit_pos / 8] >> (bit_pos % 8)) & 1;
}
static uint32_t GetBits(const uint8_t* data, size_t* bit_pos, int count) {
  uint32_t v = 0;
  for (int i = 0; i < count; i++) v |= (uint32_t)GetBit(data, (*bit_pos)++) << i;
  return v;
}
static bool ParseWbits(const uint8_t* data, size_t len, int* wbits, size_t* bits_used) {
  if (len < 1) return false;
  size_t pos = 0;
  size_t total = len * 8;
  if (total < 1) return false;
  if (GetBits(data, &pos, 1) == 0) {
    *wbits = 16;
    *bits_used = pos;
    return true;
  }
  if (total < pos + 3) return false;
  uint32_t a = GetBits(data, &pos, 3);
  if (a != 0) {
    *wbits = 17 + (int)a;
    *bits_used = pos;
    return true;
  }
  if (total < pos + 3) return false;
  uint32_t b = GetBits(data, &pos, 3);
  if (b == 0) {
    *wbits = 17;
    *bits_used = pos;
    return true;
  }
  if (b == 1) {
    if (total < pos + 7) return false;
    (void)GetBits(data, &pos, 1);
    *wbits = (int)GetBits(data, &pos, 6);
    *bits_used = pos;
    return true;
  }
  *wbits = 8 + (int)b;
  *bits_used = pos;
  return true;
}

typedef struct {
  uint8_t bytes[512];
  size_t bit_len;
} BitWriter;
static void BWWrite(BitWriter* bw, uint32_t value, int count) {
  for (int i = 0; i < count; i++) {
    size_t byte = bw->bit_len / 8;
    if (byte < sizeof(bw->bytes) && ((value >> i) & 1u)) bw->bytes[byte] |= (uint8_t)(1u << (bw->bit_len % 8));
    bw->bit_len++;
  }
}
static void BWWriteBitsFrom(BitWriter* bw, const uint8_t* data, size_t count) {
  for (size_t i = 0; i < count; i++) BWWrite(bw, (uint32_t)GetBit(data, i), 1);
}
static size_t BWFinish(BitWriter* bw) {
  return (bw->bit_len + 7) / 8;
}

typedef struct {
  bool success;
  bool read_error;
  bool write_error;
  bool corrupt;
  int reason_kind; /* 0 decoder code, 1 truncated, 2 extra, 3 comment mismatch */
  int decoder_error_code;
  bool comment_missing;
  uint64_t total_in;
  uint64_t total_out;
} OperationResult;

static bool WriteAll(FILE* output, const uint8_t* data, size_t len, const char* output_name) {
  if (len == 0) return true;
  if (fwrite(data, 1, len, output) != len) {
    fprintf(stderr, "failed to write output [%s]: %s\n", output_name, strerror(errno));
    return false;
  }
  return true;
}

/* Feed encoder input and drain direct output.  When discard is true,
   output is counted in discarded_bytes (if requested) but not written. */
static bool EncoderFeed(BrotliEncoderState* state, int op, const uint8_t* input,
                        size_t input_len, FILE* output, const char* output_name,
                        uint64_t* total_out, bool discard,
                        uint8_t* first_bytes, size_t* first_len) {
  const uint8_t* next_in = input;
  size_t avail_in = input_len;
  for (;;) {
    uint8_t* outbuf = (uint8_t*)malloc(IO_BUFFER_SIZE);
    if (!outbuf) return false;
    size_t avail_out = IO_BUFFER_SIZE;
    uint8_t* next_out = outbuf;
    int ok = BrotliEncoderCompressStream(state, op, &avail_in, &next_in, &avail_out, &next_out, NULL);
    size_t produced = IO_BUFFER_SIZE - avail_out;
    if (first_bytes && first_len && produced && *first_len == 0) {
      size_t take = produced < 16 ? produced : 16;
      memcpy(first_bytes, outbuf, take);
      *first_len = take;
    }
    if (produced && !discard) {
      if (!WriteAll(output, outbuf, produced, output_name)) {
        free(outbuf);
        return false;
      }
      if (total_out) *total_out += produced;
    }
    free(outbuf);
    if (!ok) return false;
    if (op == ENC_OP_FINISH && BrotliEncoderIsFinished(state)) break;
    if (op != ENC_OP_FINISH && avail_in == 0 && !BrotliEncoderHasMoreOutput(state)) break;
    if (op == ENC_OP_FINISH && avail_in == 0 && !BrotliEncoderHasMoreOutput(state) && BrotliEncoderIsFinished(state)) break;
  }
  return true;
}

static bool EmitMetadataPrefix(FILE* output, const char* output_name,
                               const uint8_t* flush_head, size_t flush_head_len,
                               const uint8_t* comment, size_t comment_len,
                               uint64_t* total_out) {
  int wbits = 24;
  size_t used = 4;
  if (!ParseWbits(flush_head, flush_head_len, &wbits, &used)) return false;
  BitWriter bw;
  memset(&bw, 0, sizeof(bw));
  BWWriteBitsFrom(&bw, flush_head, used);
  BWWrite(&bw, 0, 1);   /* not last */
  BWWrite(&bw, 3, 2);   /* metadata marker */
  BWWrite(&bw, 0, 1);   /* reserved */
  if (comment_len == 0) {
    BWWrite(&bw, 0, 2);
  } else {
    BWWrite(&bw, 1, 2);
    BWWrite(&bw, (uint32_t)(comment_len - 1), 8);
  }
  size_t header_len = BWFinish(&bw);
  if (!WriteAll(output, bw.bytes, header_len, output_name)) return false;
  *total_out += header_len;
  if (comment_len) {
    if (!WriteAll(output, comment, comment_len, output_name)) return false;
    *total_out += comment_len;
  }
  return true;
}

static OperationResult CompressOperation(const Params* p, FILE* input, FILE* output,
                                         const char* input_name, const char* output_name,
                                         int effective_lgwin) {
  OperationResult r;
  memset(&r, 0, sizeof(r));
  uint8_t* inbuf = (uint8_t*)malloc(IO_BUFFER_SIZE);
  if (!inbuf) return r;

  /* Read the first chunk before creating/emitting anything, matching the
     reference behaviour for unreadable inputs (e.g. directories). */
  size_t chunk_len = fread(inbuf, 1, IO_BUFFER_SIZE, input);
  if (chunk_len < IO_BUFFER_SIZE && ferror(input)) {
    fprintf(stderr, "failed to read input [%s]: %s\n", input_name, strerror(errno));
    r.read_error = true;
    free(inbuf);
    return r;
  }
  bool chunk_eof = chunk_len < IO_BUFFER_SIZE;

  BrotliEncoderState* state = BrotliEncoderCreateInstance(NULL, NULL, NULL);
  if (!state) {
    free(inbuf);
    return r;
  }
  BrotliEncoderSetParameter(state, ENC_PARAM_QUALITY, (uint32_t)p->quality);
  if (p->large_window) BrotliEncoderSetParameter(state, ENC_PARAM_LARGE_WINDOW, 1);
  BrotliEncoderSetParameter(state, ENC_PARAM_LGWIN, (uint32_t)effective_lgwin);

  bool use_dict = g_dictionary_len > 0;
  bool use_comment = p->comment_len > 0;
  if (use_dict || use_comment) {
    uint8_t flush_head[16];
    size_t flush_head_len = 0;
    if (!EncoderFeed(state, ENC_OP_FLUSH, NULL, 0, NULL, output_name, NULL, true, flush_head, &flush_head_len)) {
      goto fail_internal;
    }
    if (use_dict) {
      size_t pos = 0;
      while (pos < g_dictionary_len) {
        size_t take = g_dictionary_len - pos;
        if (take > IO_BUFFER_SIZE) take = IO_BUFFER_SIZE;
        if (!EncoderFeed(state, ENC_OP_PROCESS, g_dictionary + pos, take, NULL, output_name, NULL, true, NULL, NULL)) goto fail_internal;
        pos += take;
      }
      if (!EncoderFeed(state, ENC_OP_FLUSH, NULL, 0, NULL, output_name, NULL, true, NULL, NULL)) goto fail_internal;
    }
    if (!EmitMetadataPrefix(output, output_name, flush_head, flush_head_len,
                            use_comment ? p->comment : NULL,
                            use_comment ? p->comment_len : 0, &r.total_out)) {
      r.write_error = true;
      goto done;
    }
  }

  for (;;) {
    r.total_in += chunk_len;
    int op = chunk_eof ? ENC_OP_FINISH : ENC_OP_PROCESS;
    uint64_t before_out = r.total_out;
    if (!EncoderFeed(state, op, inbuf, chunk_len, output, output_name, &r.total_out, false, NULL, NULL)) {
      if (r.total_out == before_out) {
        /* EncoderFeed already reports write failures; a bare false here
           is an encoder failure, which the reference does not appear to
           reach for validated parameters.  Treat it as a write/internal
           failure without inventing output. */
      }
      r.write_error = true;
      goto done;
    }
    if (chunk_eof) break;
    chunk_len = fread(inbuf, 1, IO_BUFFER_SIZE, input);
    if (chunk_len < IO_BUFFER_SIZE && ferror(input)) {
      fprintf(stderr, "failed to read input [%s]: %s\n", input_name, strerror(errno));
      r.read_error = true;
      goto done;
    }
    chunk_eof = chunk_len < IO_BUFFER_SIZE;
  }

  r.success = true;
  goto done;

fail_internal:
  r.write_error = true;

done:
  BrotliEncoderDestroyInstance(state);
  free(inbuf);
  return r;
}

/* Inspect the first bytes of a (single) brotli stream for a leading
   metadata block.  Returns 0 = no leading metadata / inconclusive,
   1 = exact comment present, 2 = a metadata block is present but does
   not match the expected comment. */
static int ScanLeadingComment(const uint8_t* data, size_t len, const uint8_t* expected, size_t expected_len) {
  if (expected_len == 0 || len < 2) return 0;
  int wbits;
  size_t pos;
  if (!ParseWbits(data, len, &wbits, &pos)) return 0;
  size_t total_bits = len * 8;
  if (pos + 4 > total_bits) return 0;
  if (GetBits(data, &pos, 1) != 0) return 0;          /* ISLAST */
  if (GetBits(data, &pos, 2) != 3) return 0;          /* MNIBBLES == 3 -> metadata */
  if (GetBits(data, &pos, 1) != 0) return 0;          /* reserved */
  if (pos + 2 > total_bits) return 0;
  uint32_t skip_bytes = GetBits(data, &pos, 2);
  uint64_t meta_len = 0;
  if (skip_bytes) {
    if (pos + 8u * skip_bytes > total_bits) return 0;
    meta_len = (uint64_t)GetBits(data, &pos, 8 * (int)skip_bytes) + 1;
  }
  while (pos % 8) pos++;
  size_t byte_pos = pos / 8;
  if (meta_len != expected_len) return 2;
  if (byte_pos + meta_len > len) return 0;
  return memcmp(data + byte_pos, expected, expected_len) == 0 ? 1 : 2;
}

typedef struct {
  const Params* params;
  FILE* input;
  FILE* output;
  const char* input_name;
  const char* output_name;
  bool discard_output;
} DecodeContext;

static bool DrainDecoderOutput(BrotliDecoderState* state, DecodeContext* ctx, uint64_t* total_out) {
  while (BrotliDecoderHasMoreOutput(state)) {
    size_t sz = 0;
    const uint8_t* ptr = BrotliDecoderTakeOutput(state, &sz);
    if (sz == 0) break;
    *total_out += sz;
    if (!ctx->discard_output && !WriteAll(ctx->output, ptr, sz, ctx->output_name)) return false;
  }
  return true;
}

static OperationResult DecompressOperation(const Params* p, FILE* input, FILE* output,
                                           const char* input_name, const char* output_name,
                                           bool test_mode) {
  OperationResult r;
  memset(&r, 0, sizeof(r));
  DecodeContext ctx;
  ctx.params = p;
  ctx.input = input;
  ctx.output = output;
  ctx.input_name = input_name;
  ctx.output_name = output_name;
  ctx.discard_output = test_mode;

  uint8_t* inbuf = (uint8_t*)malloc(IO_BUFFER_SIZE);
  if (!inbuf) return r;
  size_t avail_in = 0;
  const uint8_t* next_in = NULL;
  bool eof = false;
  bool first_chunk = true;
  bool scanned = false;

  BrotliDecoderState* state = BrotliDecoderCreateInstance(NULL, NULL, NULL);
  if (!state) {
    free(inbuf);
    return r;
  }
  BrotliDecoderSetParameter(state, DEC_PARAM_LARGE_WINDOW, 1);

  for (;;) {
    if (avail_in == 0 && !eof) {
      size_t n = fread(inbuf, 1, IO_BUFFER_SIZE, input);
      if (n < IO_BUFFER_SIZE && ferror(input)) {
        fprintf(stderr, "failed to read input [%s]: %s\n", input_name, strerror(errno));
        r.read_error = true;
        break;
      }
      if (n < IO_BUFFER_SIZE) eof = true;
      r.total_in += n;
      avail_in = n;
      next_in = inbuf;
      if (first_chunk) {
        first_chunk = false;
        scanned = true;
        int scan = ScanLeadingComment(inbuf, n, p->comment, p->comment_len);
        if (scan == 2) {
          r.corrupt = true;
          r.reason_kind = 3;
          break;
        }
        if (scan == 0 && p->comment_len > 0) r.comment_missing = true;
      }
      if (n == 0) {
        r.corrupt = true;
        r.reason_kind = 1;
        break;
      }
    }

    size_t avail_out = 0;
    uint8_t* next_out = NULL;
    int result = BrotliDecoderDecompressStream(state, &avail_in, &next_in, &avail_out, &next_out, NULL);
    if (result == DEC_RESULT_NEED_MORE_OUTPUT) {
      if (!DrainDecoderOutput(state, &ctx, &r.total_out)) {
        r.write_error = true;
        break;
      }
      continue;
    }
    if (result == DEC_RESULT_SUCCESS) {
      if (!DrainDecoderOutput(state, &ctx, &r.total_out)) {
        r.write_error = true;
        break;
      }
      bool has_extra = false;
      if (avail_in > 0) {
        has_extra = true;
      } else if (!eof) {
        size_t n = fread(inbuf, 1, IO_BUFFER_SIZE, input);
        if (n < IO_BUFFER_SIZE && ferror(input)) {
          fprintf(stderr, "failed to read input [%s]: %s\n", input_name, strerror(errno));
          r.read_error = true;
          break;
        }
        if (n < IO_BUFFER_SIZE) eof = true;
        r.total_in += n;
        avail_in = n;
        next_in = inbuf;
        if (n > 0) has_extra = true;
      }
      if (!has_extra) {
        r.success = true;
        break;
      }
      if (p->concatenated) {
        if (p->verbose) fprintf(stderr, "extra input\n");
        BrotliDecoderDestroyInstance(state);
        state = BrotliDecoderCreateInstance(NULL, NULL, NULL);
        if (!state) break;
        BrotliDecoderSetParameter(state, DEC_PARAM_LARGE_WINDOW, 1);
        continue;
      }
      r.corrupt = true;
      r.reason_kind = 2;
      break;
    }
    if (result == DEC_RESULT_NEED_MORE_INPUT) {
      if (eof) {
        r.corrupt = true;
        r.reason_kind = 1;
        break;
      }
      if (avail_in > 0) {
        /* Decoder has buffered all provided bytes internally in every
           observed case; guard against a no-progress loop. */
        r.corrupt = true;
        r.reason_kind = 1;
        break;
      }
      continue;
    }
    /* Decoder error. */
    r.corrupt = true;
    r.reason_kind = 0;
    r.decoder_error_code = BrotliDecoderGetErrorCode(state);
    break;
  }

  (void)scanned;
  if (state) BrotliDecoderDestroyInstance(state);
  free(inbuf);
  return r;
}

static char* DuplicateRange(const char* s, size_t len) {
  char* out = (char*)malloc(len + 1);
  if (!out) exit(1);
  memcpy(out, s, len);
  out[len] = '\0';
  return out;
}

static bool ProcessFile(const Params* p, const char* filename) {
  const char* input_path = NULL;
  if (filename && strcmp(filename, "-") != 0) input_path = filename;
  const char* input_name = input_path ? input_path : "con";

  bool is_test = p->command == CMD_TEST;
  char* derived_output = NULL;
  const char* output_path = NULL;
  bool output_is_stdout = false;

  if (!is_test) {
    if (p->output_path) {
      output_path = p->output_path;
    } else if (p->to_stdout || !input_path) {
      output_is_stdout = true;
    } else if (p->command == CMD_COMPRESS) {
      size_t a = strlen(input_path);
      size_t b = strlen(p->suffix);
      derived_output = (char*)malloc(a + b + 1);
      if (!derived_output) return false;
      memcpy(derived_output, input_path, a);
      memcpy(derived_output + a, p->suffix, b + 1);
      output_path = derived_output;
    } else {
      const char* base = BaseName(input_path);
      size_t base_len = strlen(base);
      size_t suffix_len = strlen(p->suffix);
      size_t path_len = strlen(input_path);
      if (base_len <= suffix_len) {
        fprintf(stderr, "empty output file name for [%s] input file\n", input_path);
        return false;
      }
      if (strcmp(input_path + path_len - suffix_len, p->suffix) != 0) {
        fprintf(stderr, "input file [%s] suffix mismatch\n", input_path);
        return false;
      }
      derived_output = DuplicateRange(input_path, path_len - suffix_len);
      output_path = derived_output;
    }
  }

  const char* output_name = output_is_stdout ? "con" : (output_path ? output_path : "con");
  double start = NowSeconds();

  FILE* input = stdin;
  if (input_path) {
    input = fopen(input_path, "rb");
    if (!input) {
      fprintf(stderr, "failed to open input file [%s]: %s\n", input_path, strerror(errno));
      free(derived_output);
      return false;
    }
  }

  if ((p->command == CMD_DECOMPRESS || p->command == CMD_TEST) && !p->force &&
      isatty(fileno(input))) {
    fprintf(stderr, "Use -h help. Use -f to force input from a terminal.\n");
    if (input_path) fclose(input);
    free(derived_output);
    return false;
  }

  int effective_lgwin = 24;
  if (p->command == CMD_COMPRESS) effective_lgwin = EffectiveLgwin(p, input, input_path == NULL);

  FILE* output = NULL;
  if (!is_test) {
    if (output_is_stdout) {
      output = stdout;
    } else {
      output = OpenOutputFile(output_path, p->force);
      if (!output) {
        fprintf(stderr, "failed to open output file [%s]: %s\n", output_path, strerror(errno));
        if (input_path) fclose(input);
        free(derived_output);
        return false;
      }
    }
    if (p->command == CMD_COMPRESS && !p->force && isatty(fileno(output))) {
      fprintf(stderr, "Use -h help. Use -f to force output to a terminal.\n");
      if (!output_is_stdout) {
        fclose(output);
        remove(output_path);
      }
      if (input_path) fclose(input);
      free(derived_output);
      return false;
    }
  }

  OperationResult r;
  if (p->command == CMD_COMPRESS) {
    r = CompressOperation(p, input, output, input_name, output_name, effective_lgwin);
  } else {
    r = DecompressOperation(p, input, output, input_name, output_name, is_test);
  }

  bool success = r.success;
  bool squashed = false;

  if (success && p->verbose) {
    char in_size[64];
    char out_size[64];
    FormatSize(r.total_in, in_size, sizeof(in_size));
    FormatSize(r.total_out, out_size, sizeof(out_size));
    fprintf(stderr, "%s [%s]: %s -> %s in %.2f sec\n",
            p->command == CMD_COMPRESS ? "Compressed" : "Decompressed",
            input_name, in_size, out_size, NowSeconds() - start);
  }

  if (success && r.comment_missing) {
    fprintf(stderr, "corrupt input [%s]\n", input_name);
    if (p->verbose) fprintf(stderr, "reason: comment mismatch\n");
  }

  if (success && p->command == CMD_COMPRESS && p->squash && r.total_out >= r.total_in) {
    squashed = true;
    if (p->verbose) fprintf(stderr, "Output is larger than input\n");
  }

  if (!success && r.corrupt) {
    fprintf(stderr, "corrupt input [%s]\n", input_name);
    if (p->verbose) {
      if (r.reason_kind == 1) fprintf(stderr, "reason: truncated input\n");
      else if (r.reason_kind == 2) fprintf(stderr, "reason: extra input\n");
      else if (r.reason_kind == 3) fprintf(stderr, "reason: comment mismatch\n");
      else fprintf(stderr, "reason: %s (%d)\n", BrotliDecoderErrorString(r.decoder_error_code), r.decoder_error_code);
    }
  }

  if (output) {
    if (fclose(output) != 0) {
      if (success) {
        fprintf(stderr, "fclose failed [%s]: %s\n", output_name, strerror(errno));
        success = false;
      }
    }
    output = NULL;
  }
  if (input) {
    if (fclose(input) != 0) {
      if (success) {
        fprintf(stderr, "fclose failed [%s]: %s\n", input_name, strerror(errno));
        success = false;
      }
    }
    input = NULL;
  }

  if (!success) {
    if (output_path && !output_is_stdout) remove(output_path);
    free(derived_output);
    return false;
  }

  if (squashed) {
    if (output_path && !output_is_stdout) remove(output_path);
    free(derived_output);
    return true;
  }

  if (input_path && output_path && !output_is_stdout && !p->no_copy_stat) {
    CopyStat(input_path, output_path);
  }

  if (p->rm && input_path) remove(input_path);

  free(derived_output);
  return true;
}

int main(int argc, char** argv) {
  Params params;
  memset(&params, 0, sizeof(params));
  params.command = CMD_COMPRESS;
  params.quality = 11;
  params.lgwin = 0;
  params.suffix = ".br";

  const char* argv0 = argc > 0 && argv[0] ? argv[0] : "";
  g_program_name = BaseName(argv0);

  /* Program-name aliases, ignoring any trailing .extension. */
  {
    const char* base = g_program_name;
    size_t len = 0;
    while (base[len] && base[len] != '.') len++;
    if (len == 5 && memcmp(base, "brcat", 5) == 0) {
      params.command = CMD_DECOMPRESS;
      params.command_set = true;
      params.concatenated = true;
      params.to_stdout = true;
    } else if (len == 8 && memcmp(base, "unbrotli", 8) == 0) {
      params.command = CMD_DECOMPRESS;
      params.command_set = true;
    }
  }

  ParseArgs(&params, argc, argv);

  if (params.dictionary_path && !ReadDictionary(params.dictionary_path)) return 1;

  if (params.filename_count == 0) {
    if (!ProcessFile(&params, NULL)) return 1;
    return 0;
  }

  for (size_t i = 0; i < params.filename_count; i++) {
    if (!ProcessFile(&params, params.filenames[i])) return 1;
  }
  return 0;
}
