typedef struct {
  const Params* params;
  FILE* input;
  FILE* output;
  const char* input_name;
  const char* output_name;
  bool discard_output;
  uint64_t skip_output;
} DecodeContext;

static bool DrainDecoderOutput(BrotliDecoderState* state, DecodeContext* ctx, uint64_t* total_out) {
  while (BrotliDecoderHasMoreOutput(state)) {
    size_t sz = 0;
    const uint8_t* ptr = BrotliDecoderTakeOutput(state, &sz);
    if (sz == 0) break;
    if (ctx->skip_output > 0) {
      uint64_t take = ctx->skip_output < (uint64_t)sz ? ctx->skip_output : (uint64_t)sz;
      ptr += (size_t)take;
      sz -= (size_t)take;
      ctx->skip_output -= take;
      if (sz == 0) continue;
    }
    *total_out += sz;
    if (!ctx->discard_output && !WriteAll(ctx->output, ptr, sz, ctx->output_name)) return false;
  }
  return true;
}

/* Input source for the decoder.  In the ordinary case this is just
   fread() chunks.  When a raw dictionary is supplied, the system decoder
   library has no "attach dictionary" entry point, so the input is
   transformed on the fly: a synthetic stream first emits the dictionary
   as uncompressed meta-blocks (those output bytes are skipped by the
   caller), then the original stream body follows, bit-shifted so that it
   starts on a byte boundary after the dictionary blocks. */
typedef struct {
  FILE* file;
  const char* input_name;
  const Params* params;
  bool use_dict_transform;
  bool initialized;
  bool passthrough;
  bool passthrough_first_pending;
  bool transform_active;
  bool ended;
  bool read_error;
  uint64_t original_total;
  uint8_t* chunk_buf;
  uint8_t* orig_buf;
  bool scan_done;
  int scan_result;
  /* Dictionary transform state. */
  int synw;
  size_t wbits_bits;
  size_t dict_pos;
  bool prefix_done;
  bool body_started;
  size_t orig_len;
  size_t orig_pos;
  bool orig_eof;
  uint64_t bitbuf;
  int bitcnt;
  bool final_byte_emitted;
} InputSource;

static void WriteWbits(BitWriter* bw, int synw) {
  if (synw >= 25) {
    BWWrite(bw, 1, 1);
    BWWrite(bw, 0, 3);
    BWWrite(bw, 1, 3);
    BWWrite(bw, 0, 1);
    BWWrite(bw, (uint32_t)synw, 6);
  } else {
    BWWrite(bw, 1, 1);
    BWWrite(bw, 7, 3); /* 24 */
  }
}

static bool SourceReadOriginal(InputSource* src, uint8_t* buf, size_t* out_len, bool* short_read) {
  size_t n = fread(buf, 1, IO_BUFFER_SIZE, src->file);
  if (n < IO_BUFFER_SIZE && ferror(src->file)) {
    fprintf(stderr, "failed to read input [%s]: %s\n", src->input_name, strerror(errno));
    src->read_error = true;
    return false;
  }
  *short_read = n < IO_BUFFER_SIZE;
  *out_len = n;
  src->original_total += n;
  return true;
}

static bool SourceNext(InputSource* src, const uint8_t** ptr, size_t* len) {
  *ptr = src->chunk_buf;
  *len = 0;
  if (src->read_error) return false;

  if (!src->use_dict_transform) {
    size_t n;
    bool sr;
    if (!SourceReadOriginal(src, src->chunk_buf, &n, &sr)) return false;
    src->ended = sr;
    if (!src->scan_done) {
      src->scan_done = true;
      src->scan_result = ScanLeadingComment(src->chunk_buf, n, src->params->comment, src->params->comment_len);
    }
    *len = n;
    return true;
  }

  if (!src->initialized) {
    size_t n;
    bool sr;
    src->initialized = true;
    if (!SourceReadOriginal(src, src->orig_buf, &n, &sr)) return false;
    src->orig_len = n;
    src->orig_pos = 0;
    src->orig_eof = sr;
    src->scan_done = true;
    src->scan_result = ScanLeadingComment(src->orig_buf, n, src->params->comment, src->params->comment_len);
    int original_wbits = 0;
    size_t used = 0;
    if (n == 0 || !ParseWbits(src->orig_buf, n, &original_wbits, &used) ||
        original_wbits < 9 || original_wbits > 30) {
      src->passthrough = true;
      src->passthrough_first_pending = true;
    } else {
      src->transform_active = true;
      src->wbits_bits = used;
      if (original_wbits > 24) src->synw = original_wbits;
      else if (g_dictionary_len > ((size_t)1 << 24) - 16) src->synw = 30;
      else src->synw = 24;
      src->dict_pos = 0;
      src->prefix_done = false;
      src->body_started = false;
    }
  }

  if (src->passthrough) {
    if (src->passthrough_first_pending) {
      src->passthrough_first_pending = false;
      *ptr = src->orig_buf;
      *len = src->orig_len;
      src->ended = src->orig_eof;
      return true;
    }
    size_t n;
    bool sr;
    if (!SourceReadOriginal(src, src->chunk_buf, &n, &sr)) return false;
    src->ended = sr;
    *len = n;
    return true;
  }

  if (!src->prefix_done) {
    size_t remaining = g_dictionary_len - src->dict_pos;
    size_t seg = remaining > 65536 ? 65536 : remaining;
    BitWriter bw;
    memset(&bw, 0, sizeof(bw));
    if (src->dict_pos == 0) WriteWbits(&bw, src->synw);
    BWWrite(&bw, 0, 1);
    BWWrite(&bw, 0, 2);
    BWWrite(&bw, seg ? (uint32_t)(seg - 1) : 0, 16);
    BWWrite(&bw, 1, 1);
    size_t header_len = BWFinish(&bw);
    memcpy(src->chunk_buf, bw.bytes, header_len);
    if (seg) memcpy(src->chunk_buf + header_len, g_dictionary + src->dict_pos, seg);
    src->dict_pos += seg;
    *len = header_len + seg;
    src->ended = false;
    if (src->dict_pos >= g_dictionary_len) {
      src->prefix_done = true;
      /* Prepare the bit shifter over the original first chunk. */
      size_t start_byte = src->wbits_bits / 8;
      int shift = (int)(src->wbits_bits % 8);
      src->bitbuf = 0;
      src->bitcnt = 0;
      src->final_byte_emitted = false;
      src->body_started = true;
      if (start_byte < src->orig_len) {
        src->bitbuf = (uint64_t)(src->orig_buf[start_byte] >> shift);
        src->bitcnt = 8 - shift;
        src->orig_pos = start_byte + 1;
      } else {
        src->orig_pos = src->orig_len;
      }
    }
    return true;
  }

  /* Body: repack original bits (from wbits_bits onward) to bytes. */
  size_t out = 0;
  while (out < IO_BUFFER_SIZE) {
    if (src->bitcnt >= 8) {
      src->chunk_buf[out++] = (uint8_t)(src->bitbuf & 0xffu);
      src->bitbuf >>= 8;
      src->bitcnt -= 8;
      continue;
    }
    if (src->orig_pos < src->orig_len) {
      src->bitbuf |= (uint64_t)src->orig_buf[src->orig_pos++] << src->bitcnt;
      src->bitcnt += 8;
      continue;
    }
    if (!src->orig_eof) {
      size_t n;
      bool sr;
      if (!SourceReadOriginal(src, src->orig_buf, &n, &sr)) return false;
      src->orig_len = n;
      src->orig_pos = 0;
      src->orig_eof = sr;
      continue;
    }
    if (src->bitcnt > 0 && !src->final_byte_emitted) {
      src->chunk_buf[out++] = (uint8_t)(src->bitbuf & 0xffu);
      src->bitbuf = 0;
      src->bitcnt = 0;
      src->final_byte_emitted = true;
      continue;
    }
    break;
  }
  src->ended = src->orig_eof && src->orig_pos >= src->orig_len && src->bitcnt == 0;
  *len = out;
  return true;
}

static OperationResult DecompressOperation(const Params* p, FILE* input, FILE* output,
                                           const char* input_name, const char* output_name,
                                           bool test_mode) {
  OperationResult r;
  memset(&r, 0, sizeof(r));
  DecodeContext ctx;
  ctx.params = p;
  ctx.input = input;
  ctx.output = output;
  ctx.input_name = input_name;
  ctx.output_name = output_name;
  ctx.discard_output = test_mode;
  ctx.skip_output = 0;

  InputSource src;
  memset(&src, 0, sizeof(src));
  src.file = input;
  src.input_name = input_name;
  src.params = p;
  src.use_dict_transform = g_dictionary_len > 0 && !p->concatenated;
  src.chunk_buf = (uint8_t*)malloc(IO_BUFFER_SIZE);
  src.orig_buf = (uint8_t*)malloc(IO_BUFFER_SIZE);
  if (!src.chunk_buf || !src.orig_buf) {
    free(src.chunk_buf);
    free(src.orig_buf);
    return r;
  }

  size_t avail_in = 0;
  const uint8_t* next_in = NULL;
  bool scan_applied = false;
  bool skip_configured = false;

  BrotliDecoderState* state = BrotliDecoderCreateInstance(NULL, NULL, NULL);
  if (!state) {
    free(src.chunk_buf);
    free(src.orig_buf);
    return r;
  }
  BrotliDecoderSetParameter(state, DEC_PARAM_LARGE_WINDOW, 1);

  for (;;) {
    if (avail_in == 0 && !src.ended) {
      if (!SourceNext(&src, &next_in, &avail_in)) {
        r.read_error = true;
        break;
      }
      r.total_in = src.original_total;
      if (!scan_applied) {
        scan_applied = true;
        if (src.scan_result == 2) {
          r.corrupt = true;
          r.reason_kind = 3;
          break;
        }
        if (src.scan_result == 0 && p->comment_len > 0) r.comment_missing = true;
      }
      if (!skip_configured) {
        skip_configured = true;
        if (src.transform_active) ctx.skip_output = g_dictionary_len;
      }
      if (avail_in == 0) {
        r.corrupt = true;
        r.reason_kind = 1;
        break;
      }
    }

    size_t avail_out = 0;
    uint8_t* next_out = NULL;
    int result = BrotliDecoderDecompressStream(state, &avail_in, &next_in, &avail_out, &next_out, NULL);
    if (result == DEC_RESULT_NEED_MORE_OUTPUT) {
      if (!DrainDecoderOutput(state, &ctx, &r.total_out)) {
        r.write_error = true;
        break;
      }
      continue;
    }
    if (result == DEC_RESULT_SUCCESS) {
      if (!DrainDecoderOutput(state, &ctx, &r.total_out)) {
        r.write_error = true;
        break;
      }
      bool has_extra = false;
      if (avail_in > 0) {
        has_extra = true;
      } else if (!src.ended) {
        if (!SourceNext(&src, &next_in, &avail_in)) {
          r.read_error = true;
          break;
        }
        r.total_in = src.original_total;
        if (avail_in > 0) has_extra = true;
      }
      if (!has_extra) {
        r.success = true;
        break;
      }
      if (p->concatenated) {
        if (p->verbose) fprintf(stderr, "extra input\n");
        BrotliDecoderDestroyInstance(state);
        state = BrotliDecoderCreateInstance(NULL, NULL, NULL);
        if (!state) break;
        BrotliDecoderSetParameter(state, DEC_PARAM_LARGE_WINDOW, 1);
        continue;
      }
      r.corrupt = true;
      r.reason_kind = 2;
      break;
    }
    if (result == DEC_RESULT_NEED_MORE_INPUT) {
      if (src.ended && avail_in == 0) {
        r.corrupt = true;
        r.reason_kind = 1;
        break;
      }
      if (avail_in > 0) {
        r.corrupt = true;
        r.reason_kind = 1;
        break;
      }
      continue;
    }
    r.corrupt = true;
    r.reason_kind = 0;
    r.decoder_error_code = BrotliDecoderGetErrorCode(state);
    break;
  }

  if (state) BrotliDecoderDestroyInstance(state);
  free(src.chunk_buf);
  free(src.orig_buf);
  return r;
}
